#
# Drop code points from committed LVGL binary fonts (openrtx/fonts/*.bin) in
# place, for when the blobs cannot be regenerated byte for byte from their
# sources (docs/fonts.md).
#
# Usage:  scripts/drop_font_glyphs.py --codepoints 0xF013,0xF026 FONT.bin...
#
# Every other glyph keeps its bytes, and the head table is kept as it is but
# for the loca and glyph id formats, so the line height and the glyph header
# bit widths do not move. Before writing, every kept code point is decoded
# from the old and the new blob, metrics and pixels, and must match.

"""Drop code points from lv_font_conv binary fonts, keeping every other glyph."""

import argparse
import struct
import sys

HEAD_SIZE = 48
TABLE_HDR = 8                # u32 length, 4-char tag
CMAP_HDR = 12                # table header, u32 sub-table count
CMAP_SUB_SIZE = 16           # one cmap sub-header
LOCA_HDR = 12                # table header, u32 entry count

# Head fields, from lv_font_conv's lib/font/table_head.js.
O_LOC_FMT = 34
O_GLYPH_ID_FMT = 35
O_BPP = 37
O_XY_BITS = 38
O_WH_BITS = 39
O_ADV_BITS = 40
O_COMPRESSION = 41

# cmap sub-table formats, from lv_font_conv's lib/font/table_cmap.js.
FORMAT0 = 0
SPARSE = 1
FORMAT0_TINY = 2
SPARSE_TINY = 3

RLE_COLLAPSE_COUNT = 11      # repeat flags read before an RLE run collapses
RLE_COUNTER_BITS = 6         # width of a collapsed run's counter


def align4(data):
    """Pad bytes with zeros to a multiple of 4, as lv_font_conv's balign4."""
    return data + bytes(-len(data) % 4)


def rd_bits(data, pos, n):
    """Read an n-bit unsigned value, MSB first, at bit pos."""
    v = 0
    for p in range(pos, pos + n):
        v = (v << 1) | ((data[p >> 3] >> (7 - (p & 7))) & 1)
    return v


def rd_bits_signed(data, pos, n):
    """Read an n-bit two's-complement value at bit pos."""
    v = rd_bits(data, pos, n)
    return v - (1 << n) if n and v & (1 << (n - 1)) else v


class Font:
    """An lv_font_conv binary font: head table, code point map and glyphs."""

    def __init__(self, blob):
        """Parse a blob into its head, {code point: glyph id} and glyph bytes."""
        if blob[4:8] != b"head":
            raise ValueError("not an lv_font_conv binary font")
        self.head = bytearray(blob[:HEAD_SIZE])
        tables = {}
        off = struct.unpack_from("<I", blob, 0)[0]
        while off + TABLE_HDR <= len(blob):
            size, tag = struct.unpack_from("<I4s", blob, off)
            tables[tag] = blob[off:off + size]
            off += size
        if set(tables) != {b"cmap", b"loca", b"glyf"}:
            raise ValueError(f"tables {sorted(tables)}: only cmap, loca and "
                             "glyf are handled (build with --no-kerning)")

        self.cmap = self._read_cmap(tables[b"cmap"])
        self.glyphs = self._read_glyphs(tables[b"loca"], tables[b"glyf"])

    def _read_cmap(self, cmap):
        """Map every code point of the cmap sub-tables to its glyph id."""
        cmap_ids = {}
        count = struct.unpack_from("<I", cmap, 8)[0]
        for i in range(count):
            data_off, start, length, gid0, entries, fmt = struct.unpack_from(
                "<IIHHHB", cmap, CMAP_HDR + i * CMAP_SUB_SIZE)
            if fmt == FORMAT0_TINY:
                pairs = [(k, gid0 + k) for k in range(length)]
            elif fmt == FORMAT0:
                pairs = [(k, gid0 + d) for k, d in
                         enumerate(cmap[data_off:data_off + length]) if d]
            else:
                codes = struct.unpack_from(f"<{entries}H", cmap, data_off)
                ids = (struct.unpack_from(f"<{entries}H", cmap,
                                          data_off + 2 * entries)
                       if fmt == SPARSE else range(entries))
                pairs = [(c, gid0 + d) for c, d in zip(codes, ids)]
            cmap_ids.update((start + k, gid) for k, gid in pairs)
        return cmap_ids

    def _read_glyphs(self, loca, glyf):
        """Get the bytes of every glyph id, the last running to the glyf end."""
        count = struct.unpack_from("<I", loca, 8)[0]
        fmt = "I" if self.head[O_LOC_FMT] else "H"
        starts = struct.unpack_from(f"<{count}{fmt}", loca, LOCA_HDR)
        ends = starts[1:] + (len(glyf),)
        return [glyf[s:e] for s, e in zip(starts, ends)]

    def decode(self, code):
        """Decode a code point to (advance, x, y, w, h, pixels), or None."""
        gid = self.cmap.get(code, 0)
        if gid == 0 or gid >= len(self.glyphs) or not self.glyphs[gid]:
            return None
        h = self.head
        data = self.glyphs[gid]
        pos = 0
        adv = rd_bits(data, pos, h[O_ADV_BITS])
        pos += h[O_ADV_BITS]
        x = rd_bits_signed(data, pos, h[O_XY_BITS])
        y = rd_bits_signed(data, pos + h[O_XY_BITS], h[O_XY_BITS])
        pos += 2 * h[O_XY_BITS]
        w = rd_bits(data, pos, h[O_WH_BITS])
        hgt = rd_bits(data, pos + h[O_WH_BITS], h[O_WH_BITS])
        pos += 2 * h[O_WH_BITS]
        return (adv, x, y, w, hgt, self._pixels(data, pos, w, hgt))

    def _pixels(self, data, pos, w, h):
        """Decode a glyph's pixel values, raw or RLE as lv_font_bin.c does."""
        bpp = self.head[O_BPP]
        end = 8 * len(data)

        def take(n):
            nonlocal pos
            v = rd_bits(data, pos, n) if pos + n <= end else 0
            pos += n
            return v

        if self.head[O_COMPRESSION] == 0:
            return [take(bpp) for _ in range(w * h)]

        # RLE state machine of rle_next() in lv_font_bin.c.
        state, prev, cnt, started = "single", 0, 0, False
        out = []
        line = [0] * w
        for row in range(h):
            for col in range(w):
                if state == "single":
                    v = take(bpp)
                    if started and v == prev:
                        cnt, state = 0, "repeat"
                    started, prev = True, v
                elif state == "repeat":
                    cnt += 1
                    if take(1):
                        v = prev
                        if cnt == RLE_COLLAPSE_COUNT:
                            cnt = take(RLE_COUNTER_BITS)
                            if cnt:
                                state = "counter"
                            else:
                                v = prev = take(bpp)
                                state = "single"
                    else:
                        v = prev = take(bpp)
                        state = "single"
                else:
                    v = prev
                    cnt -= 1
                    if cnt == 0:
                        v = prev = take(bpp)
                        state = "single"
                prefilter = self.head[O_COMPRESSION] == 1 and row > 0
                line[col] = line[col] ^ v if prefilter else v
            out += line
        return out

    def drop(self, codes):
        """Remove code points, renumbering the kept glyphs in code order."""
        kept = sorted(c for c in self.cmap if c not in codes)
        self.glyphs = [b""] + [self.glyphs[self.cmap[c]] for c in kept]
        self.cmap = {c: i + 1 for i, c in enumerate(kept)}

    def to_bin(self):
        """Write the font back as lv_font_conv lays out its tables."""
        glyf = align4(struct.pack("<I4s", 0, b"glyf") + b"".join(self.glyphs))
        starts, off = [], TABLE_HDR
        for g in self.glyphs:
            starts.append(off)
            off += len(g)
        long_loca = len(glyf) > 0xFFFF
        loca = align4(struct.pack("<I4sI", 0, b"loca", len(starts))
                      + struct.pack(f"<{len(starts)}{'I' if long_loca else 'H'}",
                                    *starts))
        cmap = self._write_cmap()

        head = bytearray(self.head)
        head[O_LOC_FMT] = int(long_loca)
        head[O_GLYPH_ID_FMT] = int(len(self.glyphs) - 1 > 0xFF)
        out = b""
        for table in (bytes(head), cmap, loca, glyf):
            out += struct.pack("<I", len(table)) + table[4:]
        return out

    def _write_cmap(self):
        """Build the cmap with lv_font_conv's sub-table split and formats."""
        codes = sorted(self.cmap)
        heads, datas = [], []
        for fmt, run in cmap_split(codes):
            gid0 = self.cmap[run[0]]
            length = run[-1] - run[0] + 1
            entries = length
            if fmt == FORMAT0_TINY:
                data = b""
            elif fmt == FORMAT0:
                data = align4(bytes(self.cmap[c] - gid0 if c in self.cmap
                                    else 0 for c in range(run[0],
                                                          run[-1] + 1)))
            else:
                entries = len(run)
                data = align4(struct.pack(f"<{entries}H",
                                          *(c - run[0] for c in run)))
            heads.append((run[0], length, gid0, entries, fmt))
            datas.append(data)

        out = struct.pack("<I4sI", 0, b"cmap", len(heads))
        data_off = CMAP_HDR + CMAP_SUB_SIZE * len(heads)
        for (start, length, gid0, entries, fmt), data in zip(heads, datas):
            out += struct.pack("<IIHHHBx", data_off, start, length, gid0,
                               entries, fmt)
            data_off += len(data)
        return out + b"".join(datas)


def cmap_split(codes):
    """Split sorted code points into cmap sub-tables of the smallest total
    size, a port of lv_font_conv's lib/font/cmap_build_subtables.js."""
    best = []
    for i, ci in enumerate(codes):
        top = (float("inf"), 0, None)
        for j in range(i + 1):
            cj = codes[j]
            prev = best[j - 1][0] if j else 0
            if ci - cj < 256:
                top = min(top, (prev + 16 + ci - cj + 1, j, FORMAT0),
                          key=lambda t: t[0])
                if ci - i == cj - j:
                    top = min(top, (prev + 16, j, FORMAT0_TINY),
                              key=lambda t: t[0])
            if ci - cj < 65536:
                top = min(top, (prev + 16 + 2 * (i - j + 1), j, SPARSE_TINY),
                          key=lambda t: t[0])
        best.append(top)

    runs = []
    i = len(codes) - 1
    while i >= 0:
        _, start, fmt = best[i]
        runs.insert(0, (fmt, codes[start:i + 1]))
        i = start - 1
    return runs


def parse_codepoints(text):
    """Parse a comma-separated list of code points, e.g. 0xF013,0xF026."""
    return {int(c, 0) for c in text.split(",") if c.strip()}


def main():
    """Drop the code points from each font, checking the kept glyphs."""
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--codepoints", required=True, type=parse_codepoints,
                    help="comma-separated code points to drop, e.g. 0xF013")
    ap.add_argument("fonts", nargs="+", help="lv_font_conv .bin files, "
                    "rewritten in place")
    args = ap.parse_args()

    for path in args.fonts:
        with open(path, "rb") as f:
            old_blob = f.read()
        old = Font(old_blob)
        gone = args.codepoints & set(old.cmap)
        new = Font(old_blob)
        new.drop(args.codepoints)
        new_blob = new.to_bin()

        # The written blob must decode to the same glyphs, less the dropped.
        check = Font(new_blob)
        bad = [hex(c) for c in old.cmap if c not in args.codepoints
               and old.decode(c) != check.decode(c)]
        if bad or set(check.cmap) != set(old.cmap) - args.codepoints:
            sys.exit(f"{path}: kept glyphs changed: {', '.join(bad)}")

        with open(path, "wb") as f:
            f.write(new_blob)
        print(f"{path}: dropped {len(gone)} glyphs, {len(check.cmap)} kept "
              f"and unchanged, {len(old_blob)} -> {len(new_blob)} bytes")


if __name__ == "__main__":
    main()
